stages.sampleAnswer:
POST /auctions
  body: { itemName, startingPrice, durationSec }
  → 201 { auctionId, endsAt }

POST /auctions/:id/bids  body: { amount }, header: Idempotency-Key
  → 200 { accepted: true, currentBid, bidId }
  → 409 { accepted: false, reason: 'bid_too_low' | 'auction_ended' }

GET /auctions/:id
  → 200 { auctionId, itemName, startingPrice, currentBid, bidderId, endsAt, bids: [{ amount, timestamp, bidderId }] }
